class Customer:
    def __init__(self, name, email):
        self.name = name
        self.email = email
        self.contacts = []

    def add_contact(self, contact):
        self.contacts.append(contact)

class Contact:
    def __init__(self, name, phone, address):
        self.name = name
        self.phone = phone
        self.address = address

class CRMSystem:
    def __init__(self):
        self.customers = {}

    def add_customer(self, name, email):
        if email not in self.customers:
            self.customers[email] = Customer(name, email)
            print(f"Customer {name} added successfully.")
        else:
            print(f"Customer with email {email} already exists.")

    def add_contact(self, email, name, phone, address):
        if email in self.customers:
            self.customers[email].add_contact(Contact(name, phone, address))
            print(f"Contact {name} added successfully for customer {email}.")
        else:
            print(f"Customer with email {email} does not exist.")

    def view_customer(self, email):
        if email in self.customers:
            print(f"Customer Name: {self.customers[email].name}")
            print(f"Customer Email: {self.customers[email].email}")
            for contact in self.customers[email].contacts:
                print(f"Contact Name: {contact.name}, Phone: {contact.phone}, Address: {contact.address}")
        else:
            print(f"Customer with email {email} does not exist.")

crm = CRMSystem()
while True:
    print("\n1. Add Customer")
    print("2. Add Contact")
    print("3. View Customer")
    print("4. Exit")
    choice = input("Enter your choice: ")
    if choice == "1":
        name = input("Enter customer name: ")
        email = input("Enter customer email: ")
        crm.add_customer(name, email)
    elif choice == "2":
        email = input("Enter customer email: ")
        name = input("Enter contact name: ")
        phone = input("Enter contact phone: ")
        address = input("Enter contact address: ")
        crm.add_contact(email, name, phone, address)
    elif choice == "3":
        email = input("Enter customer email: ")
        crm.view_customer(email)
    elif choice == "4":
        break
    else:
        print("Invalid choice. Please try again.")
